-- ===========================================================================
-- CARGA DE LOS LAYOUTS DE ALMACÉN — SIMULACRO
--
-- Hace la carga COMPLETA sobre los datos reales y al final la REVIERTE.
-- Termina en ROLLBACK: al salir, la base queda exactamente como estaba.
-- Sirve para ver, con los datos de producción, qué haría la carga de verdad.
--
--   psql -f CARGA-ALMACEN-SIMULACRO.sql
--
-- Para ejecutarla en firme, cambiar el ROLLBACK final por COMMIT. Ni antes.
--
-- Advertencia sobre las secuencias: PostgreSQL NO revierte `nextval`. Después
-- del simulacro los contadores de id habrán avanzado ~3,000 y quedarán huecos
-- en la numeración. Es inofensivo —los ids no significan nada— pero explica que
-- el siguiente id no sea el que se esperaba.
--
-- Lo que escribe: costos_productos, alm_areas, obras, alm_almacenes,
-- alm_ubicaciones, alm_ajustes, alm_ajuste_detalle, alm_existencias,
-- alm_movimientos, alm_activos.
-- Lo que NO toca: ninguna otra tabla de Costos. Ni órdenes de compra, ni
-- requisiciones, ni entregas. No hay un solo DELETE ni TRUNCATE en el script.
-- ===========================================================================

\set ON_ERROR_STOP on
\timing on

BEGIN;

-- Quién autoriza el ajuste de carga inicial: el super-admin más antiguo, que es
-- a quien recurre el seeder.
CREATE TEMP TABLE carga_autoriza ON COMMIT DROP AS
SELECT u.id
FROM   usuarios u
JOIN   model_has_roles mhr ON mhr.model_uuid = u.id
JOIN   roles r             ON r.id = mhr.role_id AND r.name = 'super-admin'
ORDER  BY u.created_at
LIMIT  1;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM carga_autoriza) THEN
        RAISE EXCEPTION 'No hay ningún super-admin que pueda autorizar la carga inicial.';
    END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Los renglones del layout, tal cual. Nada de esto escribe todavía.
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE carga_insumos (
    orden       int,
    almacen     text,
    obra        text,        -- NULL = central ("está en la planta")
    descripcion text,
    unidad      text,
    area        text,
    abc         text,
    minimo      numeric,
    verifica    boolean,
    idsteelex   text,
    ubicacion   text,
    cantidad    numeric,
    costo       numeric,
    nota        text
) ON COMMIT DROP;


CREATE TEMP TABLE carga_activos (
    orden        int,
    almacen      text,
    obra         text,
    descripcion  text,
    unidad       text,
    area         text,
    abc          text,
    ubicacion    text,
    no_serie     text,
    marca        text,
    modelo       text,
    id_mto       text,
    costo        numeric,
    estatus      text,
    condicion    text,
    observaciones text
) ON COMMIT DROP;


-- Los artículos que Compras ya tenía. `costos_productos` es una sola tabla para
-- los dos módulos, así que a éstos se les abre existencia en vez de levantar un
-- gemelo. Tienen que coincidir código Y descripción: el consecutivo ART- es de
-- cada base.
CREATE TEMP TABLE carga_reuso (descripcion text, codigo text) ON COMMIT DROP;


CREATE TEMP TABLE carga_areas (descripcion text) ON COMMIT DROP;

CREATE TEMP TABLE carga_obras (no text, descripcion text) ON COMMIT DROP;

CREATE TEMP TABLE carga_centrales (clave text, nombre text, tipo text) ON COMMIT DROP;


-- ---------------------------------------------------------------------------
-- 1. Catálogo: áreas, obras y almacenes. Sólo lo que falte.
-- ---------------------------------------------------------------------------
SELECT c.descripcion, true, now(), now()
FROM   carga_areas c
WHERE  NOT EXISTS (SELECT 1 FROM alm_areas a WHERE a.descripcion = c.descripcion);

SELECT c.no, c.descripcion, true, now(), now()
FROM   carga_obras c
WHERE  NOT EXISTS (SELECT 1 FROM obras o WHERE o.no = c.no);

SELECT c.clave, c.nombre, NULL, c.tipo, true, now(), now()
FROM   carga_centrales c
WHERE  NOT EXISTS (SELECT 1 FROM alm_almacenes a WHERE a.clave = c.clave AND a.obra_id IS NULL);

-- CONST es la misma clave repetida: un almacén por obra.
SELECT DISTINCT 'CONST', 'Almacén de Construcción ' || o.no, o.id, 'montaje', true, now(), now()
FROM   (SELECT DISTINCT obra FROM carga_insumos WHERE obra IS NOT NULL
        UNION SELECT DISTINCT obra FROM carga_activos WHERE obra IS NOT NULL) x
JOIN   obras o ON o.no = x.obra
WHERE  NOT EXISTS (SELECT 1 FROM alm_almacenes a WHERE a.clave = 'CONST' AND a.obra_id = o.id);

-- Resolución de cada (clave, obra) del layout a un almacén concreto.
CREATE TEMP TABLE carga_almacenes ON COMMIT DROP AS
SELECT DISTINCT x.almacen, x.obra, a.id AS almacen_id
FROM   (SELECT almacen, obra FROM carga_insumos
        UNION SELECT almacen, obra FROM carga_activos) x
JOIN   alm_almacenes a
       ON a.clave = x.almacen
      AND ((x.obra IS NULL AND a.obra_id IS NULL)
           OR a.obra_id = (SELECT o.id FROM obras o WHERE o.no = x.obra));

DO $$
DECLARE faltan int;
BEGIN
    SELECT count(*) INTO faltan
    FROM (SELECT almacen, obra FROM carga_insumos
          UNION SELECT almacen, obra FROM carga_activos) x
    WHERE NOT EXISTS (SELECT 1 FROM carga_almacenes c
                      WHERE c.almacen = x.almacen AND c.obra IS NOT DISTINCT FROM x.obra);
    IF faltan > 0 THEN
        RAISE EXCEPTION 'Quedaron % combinaciones de almacén+obra sin resolver.', faltan;
    END IF;
END $$;


-- ---------------------------------------------------------------------------
-- 2. Ubicaciones. El layout trae el código tal como lo dice el almacenista
--    ("RACK 10", "1.1-1.3"); se guardan planas, que es como se buscan.
-- ---------------------------------------------------------------------------
SELECT DISTINCT ca.almacen_id, NULL, btrim(x.ubicacion), btrim(x.ubicacion), 'zona', true, now(), now()
FROM   (SELECT almacen, obra, ubicacion FROM carga_insumos WHERE ubicacion IS NOT NULL AND btrim(ubicacion) <> ''
        UNION SELECT almacen, obra, ubicacion FROM carga_activos WHERE ubicacion IS NOT NULL AND btrim(ubicacion) <> '') x
JOIN   carga_almacenes ca ON ca.almacen = x.almacen AND ca.obra IS NOT DISTINCT FROM x.obra
WHERE  NOT EXISTS (SELECT 1 FROM alm_ubicaciones u
                   WHERE u.almacen_id = ca.almacen_id AND u.codigo = btrim(x.ubicacion));


-- ---------------------------------------------------------------------------
-- 3. Artículos. Los que Compras ya tenía se reusan y se clasifican; el resto
--    nace con el siguiente consecutivo ART-.
-- ---------------------------------------------------------------------------

-- 3a. Reuso: se le completa lo que Almacén sí sabe. Código y descripción no se
--     tocan: son con los que se ha estado cotizando.
UPDATE costos_productos p
SET    unidad                = i.unidad,
       area_id               = ar.id,
       clasificacion_abc     = i.abc,
       stock_minimo          = i.minimo,
       tipo                  = 'insumo',
       controla_inventario   = true,
       se_controla_por_pieza = false,
       requiere_verificacion = COALESCE(i.verifica, false),
       codigo_barras         = COALESCE(NULLIF(p.codigo_barras, ''), p.codigo),
       updated_at            = now()
FROM   carga_insumos i
JOIN   carga_reuso   r  ON r.descripcion = upper(btrim(i.descripcion))
LEFT   JOIN alm_areas ar ON ar.descripcion = i.area
WHERE  p.codigo = r.codigo
  AND  upper(btrim(p.descripcion)) = r.descripcion;

-- 3b. Altas. El consecutivo arranca donde va y se reparte por orden del layout.
CREATE TEMP TABLE carga_nuevos ON COMMIT DROP AS
SELECT i.orden,
       i.descripcion,
       'ART-' || lpad((
           (SELECT COALESCE(max(substring(codigo from 5)::int), 0)
            FROM costos_productos WHERE codigo ~ '^ART-[0-9]+$')
           + row_number() OVER (ORDER BY i.orden)
       )::text, 5, '0') AS codigo
FROM   carga_insumos i
WHERE  NOT EXISTS (
           SELECT 1 FROM carga_reuso r
           JOIN costos_productos p ON p.codigo = r.codigo
                                  AND upper(btrim(p.descripcion)) = r.descripcion
           WHERE r.descripcion = upper(btrim(i.descripcion))
       );

     stock_minimo, tipo, controla_inventario, se_controla_por_pieza, requiere_verificacion,
     activo, creado_por, created_at, updated_at)
SELECT n.codigo, n.codigo, i.descripcion, i.unidad, i.idsteelex, ar.id, i.abc,
       i.minimo, 'insumo', true, false, COALESCE(i.verifica, false),
       true, (SELECT id FROM carga_autoriza), now(), now()
FROM   carga_nuevos n
JOIN   carga_insumos i ON i.orden = n.orden
LEFT   JOIN alm_areas ar ON ar.descripcion = i.area;

-- 3c. Los artículos de activo: uno por descripción, no uno por pieza.
CREATE TEMP TABLE carga_articulos_activo ON COMMIT DROP AS
SELECT min(orden) AS orden, almacen, obra, descripcion, min(unidad) AS unidad,
       min(area) AS area, min(abc) AS abc, min(ubicacion) AS ubicacion
FROM   carga_activos
GROUP  BY almacen, obra, descripcion;

CREATE TEMP TABLE carga_nuevos_activo ON COMMIT DROP AS
SELECT a.orden,
       'ART-' || lpad((
           (SELECT COALESCE(max(substring(codigo from 5)::int), 0)
            FROM costos_productos WHERE codigo ~ '^ART-[0-9]+$')
           + row_number() OVER (ORDER BY a.orden)
       )::text, 5, '0') AS codigo
FROM   carga_articulos_activo a;

     stock_minimo, tipo, controla_inventario, se_controla_por_pieza, requiere_verificacion,
     activo, creado_por, created_at, updated_at)
SELECT n.codigo, n.codigo, a.descripcion, a.unidad, ar.id, a.abc,
       NULL, 'activo', true, true, false,
       true, (SELECT id FROM carga_autoriza), now(), now()
FROM   carga_nuevos_activo n
JOIN   carga_articulos_activo a ON a.orden = n.orden
LEFT   JOIN alm_areas ar ON ar.descripcion = a.area;

-- El producto que le toca a cada renglón, ya resuelto.
CREATE TEMP TABLE carga_prod_insumo ON COMMIT DROP AS
SELECT i.orden, i.almacen, i.obra, ca.almacen_id, p.id AS producto_id,
       i.cantidad, i.costo, i.nota, i.ubicacion
FROM   carga_insumos i
JOIN   carga_almacenes ca ON ca.almacen = i.almacen AND ca.obra IS NOT DISTINCT FROM i.obra
JOIN   costos_productos p
       ON p.codigo = COALESCE(
              (SELECT n.codigo FROM carga_nuevos n WHERE n.orden = i.orden),
              (SELECT r.codigo FROM carga_reuso r WHERE r.descripcion = upper(btrim(i.descripcion)))
          );

CREATE TEMP TABLE carga_prod_activo ON COMMIT DROP AS
SELECT a.orden AS orden_articulo, a.almacen, a.obra, ca.almacen_id, p.id AS producto_id, a.ubicacion
FROM   carga_articulos_activo a
JOIN   carga_almacenes ca ON ca.almacen = a.almacen AND ca.obra IS NOT DISTINCT FROM a.obra
JOIN   carga_nuevos_activo n ON n.orden = a.orden
JOIN   costos_productos p ON p.codigo = n.codigo;


-- ---------------------------------------------------------------------------
-- 4. Un ajuste de carga inicial por almacén, con su folio del mes.
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE carga_ajustes ON COMMIT DROP AS
WITH almacenes_con_insumo AS (
    SELECT DISTINCT almacen_id FROM carga_prod_insumo
), base AS (
    SELECT COALESCE(max(substring(folio from 9)::int), 0) AS n
    FROM   alm_ajustes
    WHERE  folio ~ ('^AJU-' || to_char(now(), 'YYMM') || '[0-9]+$')
)
SELECT a.almacen_id,
       'AJU-' || to_char(now(), 'YYMM')
              || lpad((base.n + row_number() OVER (ORDER BY a.almacen_id))::text, 2, '0') AS folio
FROM   almacenes_con_insumo a CROSS JOIN base;

SELECT c.folio, c.almacen_id, 'carga_inicial', (SELECT id FROM carga_autoriza),
       current_date, 'Carga inicial del almacén.', now(), now()
FROM   carga_ajustes c;


-- ---------------------------------------------------------------------------
-- 5. Existencias. La cantidad y el valor son los del layout; el promedio sale
--    de dividirlos, que es lo que hace el ledger.
-- ---------------------------------------------------------------------------
SELECT x.almacen_id, x.producto_id, x.cantidad,
       CASE WHEN x.cantidad > 0 THEN COALESCE(x.costo, 0) ELSE 0 END,
       CASE WHEN x.cantidad > 0 THEN round(x.cantidad * COALESCE(x.costo, 0), 4) ELSE 0 END,
       u.id,
       CASE WHEN x.cantidad <> 0 THEN now() ELSE NULL END,
       now(), now()
FROM   carga_prod_insumo x
LEFT   JOIN alm_ubicaciones u ON u.almacen_id = x.almacen_id AND u.codigo = btrim(x.ubicacion);

-- Las de activo abren en cero: cada pieza les suma 1 más abajo.
SELECT x.almacen_id, x.producto_id, 0, 0, 0, u.id, now(), now()
FROM   carga_prod_activo x
LEFT   JOIN alm_ubicaciones u ON u.almacen_id = x.almacen_id AND u.codigo = btrim(x.ubicacion);


-- ---------------------------------------------------------------------------
-- 6. El renglón del ajuste y su asiento en el kardex. Contar cero deja renglón
--    pero no movimiento: es información, no un hecho que mueva saldo.
-- ---------------------------------------------------------------------------
SELECT aj.id, x.producto_id, x.cantidad, 0, x.cantidad, x.costo, x.nota, now(), now()
FROM   carga_prod_insumo x
JOIN   carga_ajustes c ON c.almacen_id = x.almacen_id
JOIN   alm_ajustes  aj ON aj.folio = c.folio;

     costo_unitario, costo_promedio_despues, valor_despues, documento_type, documento_id,
     referencia, ubicacion_id, es_reverso, observaciones, usuario_id, created_at, updated_at)
SELECT e.id, x.almacen_id, x.producto_id, 'ajuste', x.cantidad, 0, x.cantidad,
       x.costo, COALESCE(x.costo, 0), round(x.cantidad * COALESCE(x.costo, 0), 4),
       'App\Models\Alm\Ajuste', aj.id, c.folio, e.ubicacion_id, false, x.nota,
       (SELECT id FROM carga_autoriza), now(), now()
FROM   carga_prod_insumo x
JOIN   alm_existencias e ON e.almacen_id = x.almacen_id AND e.producto_id = x.producto_id
JOIN   carga_ajustes c   ON c.almacen_id = x.almacen_id
JOIN   alm_ajustes  aj   ON aj.folio = c.folio
WHERE  x.cantidad <> 0;


-- ---------------------------------------------------------------------------
-- 7. Las piezas. Cada una suma 1 a la existencia de su artículo y deja su
--    asiento; el promedio se recalcula pieza a pieza, como lo hace el ledger.
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE carga_piezas ON COMMIT DROP AS
SELECT a.orden,
       pa.almacen_id,
       pa.producto_id,
       a.no_serie, a.marca, a.modelo, a.id_mto, a.costo, a.estatus,
       a.condicion, a.observaciones, a.ubicacion,
       row_number() OVER (PARTITION BY pa.producto_id ORDER BY a.orden)                       AS n,
       sum(a.costo)  OVER (PARTITION BY pa.producto_id ORDER BY a.orden
                           ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)                   AS valor_acum
FROM   carga_activos a
JOIN   carga_articulos_activo ar
       ON ar.almacen = a.almacen AND ar.obra IS NOT DISTINCT FROM a.obra AND ar.descripcion = a.descripcion
JOIN   carga_prod_activo pa ON pa.orden_articulo = ar.orden;

     almacen_id, ubicacion_id, costo, estatus, condicion, observaciones, created_at, updated_at)
SELECT p.producto_id, p.no_serie,
       CASE WHEN p.no_serie ~ '^[A-Za-z0-9. $/+%-]+$' THEN p.no_serie
            ELSE pr.codigo || '-' || lpad(p.n::text, 2, '0') END,
       p.marca, p.modelo, p.id_mto, p.almacen_id, u.id, p.costo, p.estatus,
       p.condicion, p.observaciones, now(), now()
FROM   carga_piezas p
JOIN   costos_productos pr ON pr.id = p.producto_id
LEFT   JOIN alm_ubicaciones u ON u.almacen_id = p.almacen_id AND u.codigo = btrim(p.ubicacion);

     costo_unitario, costo_promedio_despues, valor_despues, documento_type, documento_id,
     referencia, ubicacion_id, activo_id, es_reverso, observaciones, usuario_id, created_at, updated_at)
SELECT e.id, p.almacen_id, p.producto_id, 'entrada', 1, p.n - 1, p.n,
       NULLIF(p.costo, 0), round(p.valor_acum / p.n, 4), round(p.valor_acum, 4),
       'App\Models\Alm\Activo', v.id, p.no_serie, e.ubicacion_id, v.id, false,
       'Alta de pieza', (SELECT id FROM carga_autoriza), now(), now()
FROM   carga_piezas p
JOIN   alm_existencias e ON e.almacen_id = p.almacen_id AND e.producto_id = p.producto_id
JOIN   alm_activos    v  ON v.producto_id = p.producto_id AND v.no_serie = p.no_serie;

-- Y la existencia del artículo por pieza queda en su número de piezas.
UPDATE alm_existencias e
SET    cantidad = t.piezas,
       valor    = round(t.valor, 4),
       costo_promedio = round(t.valor / t.piezas, 4),
       ultimo_movimiento_at = now(),
       updated_at = now()
FROM   (SELECT producto_id, almacen_id, count(*) AS piezas, sum(costo) AS valor
        FROM   carga_piezas GROUP BY producto_id, almacen_id) t
WHERE  e.producto_id = t.producto_id AND e.almacen_id = t.almacen_id;


-- ===========================================================================
-- VERIFICACIÓN — lo que quedaría si esto fuera en firme
-- ===========================================================================

\echo ''
\echo '=== 1. Inventario por almacén después de la carga ==='
SELECT a.clave,
       COALESCE(o.no, '(central)')                      AS obra,
       count(e.id)                                      AS renglones,
       to_char(COALESCE(sum(e.valor), 0), 'FM999,999,999.00') AS valor
FROM   alm_almacenes a
LEFT   JOIN obras o           ON o.id = a.obra_id
LEFT   JOIN alm_existencias e ON e.almacen_id = a.id
GROUP  BY a.clave, o.no
ORDER  BY a.clave, o.no NULLS FIRST;

\echo ''
\echo '=== 2. Totales. valor_cargado debe dar 8,463,304.93 ==='
SELECT (SELECT count(*) FROM costos_productos WHERE codigo LIKE 'ART-%')      AS articulos_art,
       (SELECT count(*) FROM alm_existencias)                                 AS existencias,
       (SELECT count(*) FROM alm_movimientos)                                 AS movimientos,
       (SELECT count(*) FROM alm_activos)                                     AS piezas,
       (SELECT count(*) FROM alm_ubicaciones)                                 AS ubicaciones,
       to_char((SELECT COALESCE(sum(cantidad * costo), 0) FROM carga_insumos)
             + (SELECT COALESCE(sum(costo), 0) FROM carga_activos), 'FM999,999,999.00') AS valor_cargado;

\echo ''
\echo '=== 3. Artículos de Compras que se reusaron (deben ser 44) ==='
SELECT count(*) AS reusados
FROM   carga_reuso r
JOIN   costos_productos p ON p.codigo = r.codigo AND upper(btrim(p.descripcion)) = r.descripcion;

\echo ''
\echo '=== 4. INVARIANTE: la existencia de un artículo por pieza es su número de piezas ==='
SELECT count(*) AS descuadres
FROM   alm_existencias e
JOIN   costos_productos p ON p.id = e.producto_id AND p.se_controla_por_pieza
WHERE  e.cantidad <> (SELECT count(*) FROM alm_activos v
                      WHERE v.producto_id = e.producto_id
                        AND v.almacen_id = e.almacen_id
                        AND v.estatus <> 'baja');

\echo ''
\echo '=== 5. INVARIANTE: ninguna existencia con valor sin cantidad, ni al revés ==='
SELECT count(*) AS incoherentes
FROM   alm_existencias
WHERE  (cantidad = 0 AND valor <> 0) OR (cantidad < 0);

\echo ''
\echo '=== 6. COSTOS INTACTO. Compara con lo que medimos antes: 109, 336, 14, 82, 74 ==='
SELECT (SELECT count(*) FROM costos_ordenes_compra)                                   AS ordenes_compra,
       (SELECT count(*) FROM costos_ordenes_compra_detalle)                           AS renglones_oc,
       (SELECT count(*) FROM costos_ordenes_compra_detalle WHERE producto_id IS NULL) AS oc_sin_producto,
       (SELECT count(*) FROM costos_requisicion_detalle    WHERE producto_id IS NULL) AS req_sin_producto,
       (SELECT count(*) FROM costos_entregas               WHERE almacen_id IS NULL)  AS recepciones_sin_almacen;

\echo ''
\echo '=== 7. Artículos que quedarían duplicados por descripción (debe salir vacío) ==='
SELECT upper(btrim(descripcion)) AS descripcion, count(*) AS veces,
       string_agg(codigo, ', ' ORDER BY codigo) AS codigos
FROM   costos_productos
GROUP  BY upper(btrim(descripcion))
HAVING count(*) > 1
ORDER  BY count(*) DESC, 1
LIMIT  40;


-- ===========================================================================
-- Se revierte todo. Para ejecutar en firme, cambiar esta línea por COMMIT;
-- ===========================================================================
ROLLBACK;

\echo ''
\echo '>>> ROLLBACK hecho. La base quedó como estaba.'
\echo '>>> Para cargar en firme: cambia el ROLLBACK final por COMMIT y vuelve a correrlo.'
